import{_ as e,c as r,o as l,a8 as n}from"./chunks/framework.BX9uSPFk.js";const c=JSON.parse('{"title":"🚀 Web 前端架构演进：从 100 到 1,000,000 用户","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/100 用户到 100 万用户.md","filePath":"engineering/100 用户到 100 万用户.md"}'),o={name:"engineering/100 用户到 100 万用户.md"};function a(s,t,i,g,d,h){return l(),r("div",null,t[0]||(t[0]=[n('<h1 id="🚀-Web-前端架构演进-从-100-到-1-000-000-用户" tabindex="-1">🚀 Web 前端架构演进：从 100 到 1,000,000 用户 <a class="header-anchor" href="#🚀-Web-前端架构演进-从-100-到-1-000-000-用户" aria-label="Permalink to &quot;🚀 Web 前端架构演进：从 100 到 1,000,000 用户&quot;">​</a></h1><p>当用户量级发生质变时，前端的工作重心会从“功能实现”转向“系统工程”。</p><h2 id="_1-资源加载与构建优化" tabindex="-1">1. 资源加载与构建优化 <a class="header-anchor" href="#_1-资源加载与构建优化" aria-label="Permalink to &quot;1. 资源加载与构建优化&quot;">​</a></h2><ul><li><strong>100 用户</strong>：单个大 Bundle 即可，基础 Webpack 配置。</li><li><strong>1,000,000 用户</strong>：</li><li><strong>代码分割 (Code Splitting)</strong>：首页 JS 严控在 200KB 内。</li><li><strong>构建工具</strong>：使用 <strong>Vite/esbuild</strong> 提升速度，<strong>Rollup</strong> 优化体积。</li><li><strong>CDN 分发</strong>：全站静态资源托管至边缘节点，开启 Brotli 压缩。</li></ul><h2 id="_2-运行时性能对比" tabindex="-1">2. 运行时性能对比 <a class="header-anchor" href="#_2-运行时性能对比" aria-label="Permalink to &quot;2. 运行时性能对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">100 用户 (初创期)</th><th style="text-align:left;">1,000,000 用户 (成熟期)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>首屏策略</strong></td><td style="text-align:left;">简单 Loading 动画</td><td style="text-align:left;"><strong>骨架屏 (Skeleton Screen)</strong> + 关键 CSS 内联</td></tr><tr><td style="text-align:left;"><strong>数据请求</strong></td><td style="text-align:left;">直接 Fetch / Axios</td><td style="text-align:left;"><strong>SWR / React Query</strong> 缓存，实现秒开</td></tr><tr><td style="text-align:left;"><strong>图片工程</strong></td><td style="text-align:left;">原图展示</td><td style="text-align:left;">动态 <strong>WebP</strong> 转换 + 响应式尺寸适配</td></tr></tbody></table><h2 id="_3-稳定性与监控-不可或缺-" tabindex="-1">3. 稳定性与监控 (不可或缺) <a class="header-anchor" href="#_3-稳定性与监控-不可或缺-" aria-label="Permalink to &quot;3. 稳定性与监控 (不可或缺)&quot;">​</a></h2><p>在百万量级下，任何微小的 Bug 都会被放大。</p><ul><li><strong>错误捕获</strong>：接入 <strong>Sentry</strong>，实时监控 JS 错误和资源加载异常。</li><li><strong>灰度发布</strong>：利用 <strong>Feature Flags</strong> 控制功能开关，先对 1% 用户开放。</li><li><strong>容错设计</strong>：局部组件崩溃时不影响整站，提供优雅的降级 UI。</li></ul><h2 id="_4-实时通信-WebSocket-" tabindex="-1">4. 实时通信 (WebSocket) <a class="header-anchor" href="#_4-实时通信-WebSocket-" aria-label="Permalink to &quot;4. 实时通信 (WebSocket)&quot;">​</a></h2><ul><li><strong>连接管理</strong>：实现<strong>指数退避重连机制</strong>，防止百万客户端同时重连压垮服务器。</li><li><strong>状态感知</strong>：根据页面可见性（Page Visibility）智能挂起或恢复连接。</li></ul><h2 id="_5-安全性防范" tabindex="-1">5. 安全性防范 <a class="header-anchor" href="#_5-安全性防范" aria-label="Permalink to &quot;5. 安全性防范&quot;">​</a></h2><ul><li><strong>CSP (内容安全策略)</strong>：严格限制脚本来源，根除 XSS 注入。</li><li><strong>SRI (子资源完整性)</strong>：确保 CDN 资源未被篡改。</li><li><strong>接口防刷</strong>：引入人机校验与行为轨迹分析。</li></ul><hr><blockquote><p><strong>总结</strong>：100 用户看的是<strong>逻辑</strong>，100 万用户看的是<strong>工程</strong>。</p></blockquote>',15)]))}const u=e(o,[["render",a]]);export{c as __pageData,u as default};
